  // A: spread along a line -> counts vary (2 3 3 2 0 0), two isolated particles
  float ax[6] = { 0.0f, 0.5f, 1.0f, 2.5f, 5.0f, 20.0f };
  float ay[6] = { 0, 0, 0, 0, 0, 0 }, az[6] = { 0, 0, 0, 0, 0, 0 };
