#ifdef TEST_GAUSSDATA_DV
// Vandermonde system data (test/unit/gaussdata.sis) -- the matrix and RHS the
// Gauss solvers are fed.  A[i,j] = exp(j, i-1) = j^(i-1) from a CROSS forall;
// B[j] = 1.0 if j = m else 0.0.
//
// Two things pinned here:
//   * two-argument `exp` is POWER, not e^x.  Sisal's exp(b,n) = b^n while
//     exp(x) / etothe(x) are e^x.  A test using e^x would still produce
//     numbers, so the reference computes j^(i-1) explicitly.
//   * the CROSS forall with `array_dv of` comes back RANK 2, dims (n,n),
//     row-major -- measured rather than assumed; forall_spec.md describes the
//     flat rank-1 default for the `array of` form, so rank and dims are
//     checked, not just contents.
// Cross-checked against OSC 13.0.3 (which returns it as an array of rows).
static void test_gaussdata_dv (void)
{
  printf ("\n=== Group: gaussdata_dv (cross forall, 2-arg exp is power) ===\n");
  for (int32_t n : { 1, 2, 4, 6 })
    {
      std::vector<double> A ((size_t)n * n), B (n, 0.0);
      for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++)
          {
            double v = 1.0;                       // j^(i-1), by repeated multiply
            for (int e = 0; e < i - 1; e++) v *= (double)j;
            A[(size_t)(i - 1) * n + (j - 1)] = v;
          }
      B[0] = 1.0;                                  // FormB(n, 1)

      GD_results r = func_MAIN (n);
      char msg[176];
      snprintf (msg, sizeof msg, "n=%d passthrough and B = e_1", n);
      check (msg, r.n == n && (int)r.b.size == n
                      && [&] { for (int j = 0; j < n; j++)
                                 if (!near_d (((const double *)r.b.data)[j], B[j]))
                                   return false;
                               return true; }());
      snprintf (msg, sizeof msg, "n=%d A is rank 2, dims (%d,%d)", n, n, n);
      check (msg, r.a.rank == 2 && (int)r.a.dims[0] == n
                      && (int)r.a.dims[1] == n && (int)r.a.size == n * n);
      bool ok = ((int)r.a.size == n * n);
      for (size_t k = 0; ok && k < A.size (); k++)
        ok = ok && near_d (((const double *)r.a.data)[k], A[k]);
      snprintf (msg, sizeof msg, "n=%d A[i,j] == j^(i-1) (exp is POWER)", n);
      check (msg, ok);
    }
}
#endif
#ifdef TEST_ARSIEVE_DV
// Sieve of Eratosthenes over a flag ARRAY (test/unit/arsieve.sis).  The suite's
// other sieves are all stream formulations; this one covers:
//   * a NESTED for-initial with an ARRAY carry at BOTH levels -- outer over j
//     carrying the flags, inner marking loop over i carrying its own copy;
//   * an IF whose result is an ARRAY (composite j returns `old a` unchanged),
//     where a copy-vs-alias mistake is invisible in the flags and shows in the
//     primes;
//   * single-element replace inside the inner loop, on the carry being built;
//   * a masked STREAM gather to finish.
//
// Flags are INTEGER 0/1, not CHARACTER '0'/'1' as in the source: the character
// version is miscompiled today (1-byte elements written at a 4-byte stride, so
// the sieve returns near-garbage where OSC gives the right primes -- see
// project_bool_array_1byte_ops).  The flag type is incidental to every shape
// above.
static void test_arsieve_dv (void)
{
  printf ("\n=== Group: arsieve_dv (array sieve, nested array carries) ===\n");
  for (int32_t n : { 2, 3, 10, 30, 50, 97 })
    {
      // reference: an independent sieve
      std::vector<bool> composite (n + 1, false);
      for (int p = 2; (long)p * p <= n; p++)
        if (!composite[p])
          for (int q = p * p; q <= n; q += p) composite[q] = true;
      std::vector<int32_t> primes;
      for (int k = 2; k <= n; k++) if (!composite[k]) primes.push_back (k);

      std::vector<int32_t> got;
      for (auto g = func_MAIN (n); !sisal_stream_empty_pred (g);
           g = sisal_stream_rest (g))
        got.push_back (sisal_stream_first<int32_t> (g));

      char msg[160];
      snprintf (msg, sizeof msg, "n=%-3d yields %d primes", n,
                (int)primes.size ());
      check (msg, got.size () == primes.size ());
      bool ok = (got.size () == primes.size ());
      for (size_t i = 0; ok && i < primes.size (); i++)
        ok = ok && (got[i] == primes[i]);
      snprintf (msg, sizeof msg, "n=%-3d the primes match an independent sieve",
                n);
      check (msg, ok);
    }
}
#endif
#ifdef TEST_INITAL_DV
// Inital -- spectral shallow-water model initialisation (test/unit/Inital.sis).
// Thirteen return values in one function, covering together:
//   * a forall returning TWO arrays at once (kmjx / kmjxx from one loop);
//   * `value of CATENATE` over a forall whose body is itself a forall -- the
//     epsilon table, mx blocks of jxx values flattened into one array of mx*jxx;
//   * a single-element replace on that result, epsilon_a[1 : 0.0], which exists
//     because the first entry would be sqrt(0 / -1);
//   * a 13-tuple return mixing integer, real and array types.
// Cross-checked against OSC 13.0.3.
static void test_inital_dv (void)
{
  printf ("\n=== Group: inital_dv (13-tuple, catenate over nested foralls) ===\n");
  struct Cfg { int ir, ilong, ilat, mx, jx, jxx; float zmean1; };
  const Cfg cfgs[] = { { 4, 8, 6, 3, 5, 7, 2.0f }, { 2, 4, 4, 2, 3, 3, 1.0f },
                       { 6, 12, 10, 4, 6, 8, 0.5f }, { 1, 2, 2, 1, 1, 2, 3.0f } };
  for (const Cfg &cf : cfgs)
    {
      const float ww = 7.292E-5f, tw = ww * 2.0f;
      const float asq = 6371.22E3f * 6371.22E3f, grav = 9.80616f;
      const float zmean = cf.zmean1 * grav / asq;
      const int ilath = cf.ilat / 2, irmax2 = cf.ir + 2;
      std::vector<int32_t> kmjx (cf.mx), kmjxx (cf.mx), ksq (cf.ir * 2);
      for (int m = 1; m <= cf.mx; m++)
        { kmjx[m - 1] = (m - 1) * cf.jx; kmjxx[m - 1] = (m - 1) * cf.jxx; }
      for (int j = 1; j <= cf.ir * 2; j++) ksq[j - 1] = j * (j + 1);
      std::vector<float> eps;
      for (int mp = 1; mp <= cf.mx; mp++)          // catenate over mp
        for (int j = 1; j <= cf.jxx; j++)          //   inner forall over j
          {
            int l = j + mp - 2, m = mp - 1;
            float t = (float)((l + m) * (l - m));
            float b = (float)(4 * l * l - 1);
            eps.push_back (sqrtf (t / b));
          }
      eps[0] = 0.0f;                                // epsilon_a[1 : 0.0]

      INIT_results r = func_MAIN (cf.ir, cf.ilong, cf.ilat, cf.mx, cf.jx,
                                  cf.jxx, cf.zmean1);
      char msg[190];
      snprintf (msg, sizeof msg, "ir=%d mx=%d jxx=%d scalars", cf.ir, cf.mx,
                cf.jxx);
      check (msg, r.ir == cf.ir && r.ilong == cf.ilong && r.ilath == ilath
                      && r.irmax2 == irmax2 && fabs (r.ww - ww) < 1e-12
                      && fabs (r.tw - tw) < 1e-12
                      && fabs (r.grav - grav) < 1e-5
                      && fabs ((double)r.asq - (double)asq) < 1e6
                      && fabs ((double)r.zmean - (double)zmean) < 1e-18);
      auto samei = [] (sisal_array_t a, const std::vector<int32_t> &w) {
        if ((int)a.size != (int)w.size ()) return false;
        for (size_t i = 0; i < w.size (); i++)
          if (((const int32_t *)a.data)[i] != w[i]) return false;
        return true;
      };
      snprintf (msg, sizeof msg, "ir=%d mx=%d two arrays from one forall", cf.ir,
                cf.mx);
      check (msg, samei (r.kmjx, kmjx) && samei (r.kmjxx, kmjxx));
      snprintf (msg, sizeof msg, "ir=%d ksq is j(j+1) for j=1..%d", cf.ir,
                cf.ir * 2);
      check (msg, samei (r.ksq, ksq));
      bool eok = ((int)r.epsilon.size == cf.mx * cf.jxx);
      for (size_t i = 0; eok && i < eps.size (); i++)
        eok = eok && (fabs ((double)((const float *)r.epsilon.data)[i]
                            - (double)eps[i]) < 1e-6);
      snprintf (msg, sizeof msg,
                "ir=%d mx=%d jxx=%d catenate gives %d epsilons, [1] replaced",
                cf.ir, cf.mx, cf.jxx, cf.mx * cf.jxx);
      check (msg, eok);
    }
}
#endif
#ifdef TEST_PASSGRID_DV
// PassGrid, the GRID-direction FFT pass dispatcher (test/unit/PassGrid.sis).
// Companion to passfreq_dv, and the reason the three ifg_*_dv kernels were
// promoted.  The derivation is TRANSPOSED against PassFreq's, which is the
// whole point of having both:
//
//     PassFreq:  jink = inc2*m;  iink = inc1*la;  jump = (ifac-1)*iink
//     PassGrid:  iink = inc1*m;  jink = inc2*la;  jump = (ifac-1)*jink
//
// Same igo mapping, different parameters and a different kernel family.  A
// transposition error in the derivation passes passfreq_dv and fails here.
static void test_passgrid_dv (void)
{
  printf ("\n=== Group: passgrid_dv (grid dispatch, transposed derivation) ===\n");
  struct Cfg { int n, ifac, la, inc1, inc2; };
  const Cfg cfgs[] = { { 16, 2, 1, 2, 1 }, { 24, 3, 1, 2, 1 },
                       { 32, 4, 1, 2, 1 }, { 48, 3, 2, 2, 1 },
                       { 64, 4, 2, 2, 1 }, { 32, 2, 2, 1, 1 } };
  const int NEL = 400;
  for (const Cfg &cf : cfgs)
    {
      const int m = cf.n / cf.ifac, iink = cf.inc1 * m, jink = cf.inc2 * cf.la,
                jump = (cf.ifac - 1) * jink, igo = cf.ifac - 1;
      std::vector<float> a (NEL + 1), ci (NEL + 1, 0.f), trigs (NEL + 1);
      for (int i = 1; i <= NEL; i++)
        { a[i] = (float)i / 8.0f; trigs[i] = (float)i / 16.0f; }
      std::vector<float> ref
          = (igo == 2) ? ifg3ref::kernel (m, cf.la, iink, jink, jump, cf.inc1,
                                          cf.inc2, a, ci, trigs)
            : (igo == 3) ? ifg4ref::kernel (m, cf.la, iink, jink, jump, cf.inc1,
                                            cf.inc2, a, ci, trigs)
                         : ifg2ref::kernel (m, cf.la, iink, jink, jump, cf.inc1,
                                            cf.inc2, a, ci, trigs);
      auto mk = [&] (const std::vector<float> &src) {
        sisal_array_t A = sisal_array_alloc_empty (1, 3, (uint64_t)NEL);
        A.dims[0] = NEL; A.lower_bound[0] = 1;
        for (int i = 1; i <= NEL; i++) ((float *)A.data)[i - 1] = src[i];
        return A;
      };
      sisal_array_t aa = mk (a), cc = mk (ci), tt = mk (trigs);
      sisal_array_t r = func_MAIN (cf.inc1, cf.inc2, cf.n, cf.ifac, cf.la, aa,
                                   cc, tt);
      char msg[190];
      snprintf (msg, sizeof msg,
                "n=%-2d ifac=%d la=%d -> grid radix %d, %d reals", cf.n,
                cf.ifac, cf.la, igo == 2 ? 3 : igo == 3 ? 4 : 2, NEL);
      check (msg, (int)r.size == NEL && r.rank == 1);
      bool ok = ((int)r.size == NEL);
      for (int i = 1; ok && i <= NEL; i++)
        ok = ok && (fabs ((double)((const float *)r.data)[i - 1]
                          - (double)ref[i]) < 1e-5);
      snprintf (msg, sizeof msg,
                "n=%-2d ifac=%d la=%d transposed derivation matches", cf.n,
                cf.ifac, cf.la);
      check (msg, ok);
    }
}
#endif
